import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique {@link File} inside {@code dir} with the given {@code name}.
     * <p>
     * The method validates that the resolved path stays within {@code dir} to
     * prevent directory‑traversal attacks. It also normalises the path,
     * rejects absolute names, and guarantees that the parent directories exist.
     *
     * @param dir  the base directory where the file should be created; must not be {@code null}
     * @param name the desired file name; must not be {@code null}
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if {@code dir} is not a directory, if {@code name}
     *                                  resolves outside {@code dir}, or if {@code name}
     *                                  contains an absolute path
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new NullPointerException("dir must not be null");
        }
        if (name == null) {
            throw new NullPointerException("name must not be null");
        }
        if (!dir.isDirectory()) {
            throw new IllegalArgumentException("Provided dir is not a directory: " + dir);
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve and normalise the target path
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Reject absolute names and ensure the target stays within the base directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                    "Attempted to create a file outside the allowed directory: " + name);
        }

        File file = targetPath.toFile();

        // Determine prefix/suffix for generating a unique filename
        int dot = name.indexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Ensure parent directories exist
        File parent = file.getParentFile();
        if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
            throw new RuntimeException("Failed to create directories for: " + parent);
        }

        return file;
    }

    // other methods
}
