import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely expands entries from the supplied archive into the target directory.
     *
     * <p>All entry names are validated to ensure they cannot escape the target directory.
     * Absolute paths, paths containing {@code ..} components, or paths that resolve to
     * locations outside the target directory are rejected.  Symbolic links are also
     * prohibited to prevent accidental overwrite of files outside the extraction
     * area.</p>
     *
     * @param supplier      provides the next readable entry from the archive
     * @param writer        writes the entry data to the output stream
     * @param targetDirectory the root directory where entries should be extracted
     * @throws IOException if an I/O error occurs or a security violation is detected
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the target directory once
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            // Reject absolute entry names – they would ignore the target directory
            Path entryPath = Paths.get(nextEntry.getName());
            if (entryPath.isAbsolute()) {
                throw new IOException("Entry name is absolute: " + nextEntry.getName());
            }

            // Normalize to collapse any '..' or '.' segments
            Path normalizedEntryPath = entryPath.normalize();

            // Resolve the destination path and normalize again
            Path destPath = targetDirPath.resolve(normalizedEntryPath).normalize();

            // Ensure the destination is still inside the target directory
            if (!destPath.startsWith(targetDirPath)) {
                throw new IOException("Expanding " + nextEntry.getName()
                        + " would create file outside of " + targetDirectory);
            }

            // Prevent writing through a symbolic link that points outside the target dir
            if (Files.isSymbolicLink(destPath)) {
                throw new IOException("Destination is a symbolic link: " + destPath);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory (and any missing parents)
                Files.createDirectories(destPath);
            } else {
                // Ensure parent directories exist
                Path parent = destPath.getParent();
                if (parent != null) {
                    Files.createDirectories(parent);
                }

                // Write the file contents
                try (OutputStream out = Files.newOutputStream(destPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
```

