private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor by delegating to the cached stream.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // Cache the entry data.
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Validate the declared size of the entry.
    if (csize < 0) {
        throw new IOException("Invalid entry size: " + csize);
    }

    // If we've already read the declared amount, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Prevent reading past the declared size.
    long remaining = csize - current.bytesRead;
    if (remaining <= 0) {
        return -1;
    }

    // Refill the internal buffer if it is exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        int l = in.read(buf.array());
        if (l == -1) {
            // Underlying stream ended unexpectedly – treat as EOF.
            return -1;
        }
        if (l == 0) {
            // A zero‑length read indicates a malformed stream; abort to avoid an infinite loop.
            throw new IOException("Underlying stream returned zero bytes");
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;

        // Sanity check: we should never read more bytes than the entry declares.
        if (current.bytesReadFromStream > csize) {
            throw new IOException("Read more bytes (" + current.bytesReadFromStream +
                    ") than declared entry size (" + csize + ")");
        }
    }

    // Determine how many bytes to copy from the buffer.
    int toRead = Math.min(buf.remaining(), length);
    if (remaining < toRead) {
        toRead = (int) remaining;
    }

    // Defensive check: if nothing remains to read, signal EOF.
    if (toRead <= 0) {
        return -1;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
