     * {@link DocumentBuilderFactory} that has been configured to mitigate XXE
     * attacks. The factory disables DTDs, external entities, and schema loading.
     *
     * @param inputSource the source to parse
     * @return a parsed {@link Document}
     * @throws IOException          if an I/O error occurs
     * @throws SAXException         if a parsing error occurs
     * @throws ParserConfigurationException if a configuration error occurs
     */
    private Document parseSecure(InputSource inputSource)
            throws IOException, SAXException, javax.xml.parsers.ParserConfigurationException {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // Enable secure processing
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // Disable DOCTYPE declaration
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // Disable external entities
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
