     * @param toVersion   the target version string
     * @return a negative integer if {@code fromVersion} is less than
     * {@code toVersion}, zero if they are equal, or a positive integer
     * otherwise
     * @throws IllegalArgumentException if either argument is {@code null}
     *                                  or does not match the expected format
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        if (fromVersion == null || toVersion == null) {
            throw new IllegalArgumentException("Version strings cannot be null");
        }

        String[] fromArr = fromVersion.split("\\.");
        String[] toArr = toVersion.split("\\.");

        if (fromArr.length != 3 || toArr.length != 3) {
            throw new IllegalArgumentException(
                "Invalid version format: expected 'x.y.z'");
        }

        try {
            int fromFirst = Integer.parseInt(fromArr[0]);
            int fromMiddle = Integer.parseInt(fromArr[1]);
            int fromEnd = Integer.parseInt(fromArr[2]);

            int toFirst = Integer.parseInt(toArr[0]);
            int toMiddle = Integer.parseInt(toArr[1]);
            int toEnd = Integer.parseInt(toArr[2]);

            int cmp = Integer.compare(fromFirst, toFirst);
            if (cmp != 0) {
                return cmp;
            }

            cmp = Integer.compare(fromMiddle, toMiddle);
            if (cmp != 0) {
                return cmp;
            }

            return Integer.compare(fromEnd, toEnd);
        } catch (NumberFormatException e) {
            // If any component is not a valid integer, treat the versions as equal
            // to avoid crashing the application. In a real-world scenario,
            // consider logging the incident.
            return 0;
        }
    }

