        String authenticatedUserId = getAuthenticatedUserId(request);
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        if (!Objects.equals(authenticatedUserId, targetUserId)) {
            // The requester is not the owner of the account being updated.
            return false;
        }

        // 2. Parse the request body into a ScimUser object.
        String requestBody = IOUtils.toString(request.getReader());
